scwin.fn_Period = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=PERIOD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.select.period.condition";
    dts_Period.DataID = encodeURI(url);
    dts_Period.reset();
    dts_mktpartcList.DataID = "/CodeAction.do?method=listRepMajagntCom&For=R";
    dts_mktpartcList.reset();
};
scwin.fn_list_sync = function() {
    if (chk_all.checked) {
        scwin.pCheckAll = "2";
    } else {
        scwin.pCheckAll = "1";
    }
    if (MxTab_1.getSelectedTabIndex() == 1) {
        var url = "/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectRepMajagntTotal&inputMessageId=REPMAJAGNT_TOTAL_OUT" + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&STRT_DD=" + $c.stf.getObjectValue(edt_SDate_all) + "&TYPE_CD=1" + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Mbr_List_all.DataID = encodeURI(url);
        dts_Mbr_List_all.reset();
        $c.cm.ShowWin(grd_Mbr_List_all);
    } else if (MxTab_1.getSelectedTabIndex() == 2) {
        var url = "/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectRepMajagntStockCom&inputMessageId=PUBOFRPRC_STOCKRTO_OUT" + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&MBR_NO=A" + "&TYPE_CD=2" + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Mbr_List_1.DataID = encodeURI(url);
        dts_Mbr_List_1.reset();
        var url = "/RepMajagnt.do?method=selectRepMajagntNetincmCalcCom&inputMessageId=PUBOFRPRC_NETINCM_OUT" + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&MBR_NO=A" + "&TYPE_CD=2" + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Mbr_List_2.DataID = encodeURI(url);
        dts_Mbr_List_2.reset();
        var url = "/RepMajagnt.do?method=selectRepMajagntDDCom&inputMessageId=DUE_DIlIGENCE_OUT" + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&STRT_DD=" + $c.stf.getObjectValue(edt_SDate_all) + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Mbr_List_3.DataID = encodeURI(url);
        dts_Mbr_List_3.reset();
        var url = "/RepMajagnt.do?method=selectRepMajagntStockContrbtCom&inputMessageId=STOCK_CONTRBT_OUT" + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Mbr_List_4.DataID = encodeURI(url);
        dts_Mbr_List_4.reset();
        //ShowWin(grd_Mbr_List_14);

    } else if (MxTab_1.getSelectedTabIndex() == 3) {
        var mktpartcList;
        if (cmd_mktpartcList.BindColVal == "") {
            mktpartcList = "A";
            $c.cm.setColumnProp(grd_Com_List_1, "LEADCOM_MBR_NM", "Show", "true");
            $c.cm.setColumnProp(grd_Com_List_2, "LEADCOM_MBR_NM", "Show", "true");
            $c.cm.setColumnProp(grd_Com_List_2, "LIST_SHRS", "Show", "true");
            $c.cm.setColumnProp(grd_Com_List_3, "LEADCOM_MBR_NM", "Show", "true");
            $c.cm.setColumnProp(grd_Com_List_4, "LEADCOM_MBR_NM", "Show", "true");
        } else {
            mktpartcList = cmd_mktpartcList.BindColVal;
            $c.cm.setColumnProp(grd_Com_List_1, "LEADCOM_MBR_NM", "Show", "false");
            $c.cm.setColumnProp(grd_Com_List_2, "LEADCOM_MBR_NM", "Show", "false");
            $c.cm.setColumnProp(grd_Com_List_2, "LIST_SHRS", "Show", "false");
            $c.cm.setColumnProp(grd_Com_List_3, "LEADCOM_MBR_NM", "Show", "false");
            $c.cm.setColumnProp(grd_Com_List_4, "LEADCOM_MBR_NM", "Show", "false");
        }
        var url = "/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectRepMajagntStockCom&inputMessageId=PUBOFRPRC_STOCKRTO_OUT" + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&MBR_NO=" + mktpartcList + "&TYPE_CD=3" + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Com_List_1.DataID = encodeURI(url);
        dts_Com_List_1.reset();
        var url = "/RepMajagnt.do?method=selectRepMajagntNetincmCalcCom&inputMessageId=PUBOFRPRC_NETINCM_OUT" + "&YYYY=" + scwin.periodYYYY + "&VALU_TP_CD=" + scwin.periodTmCd + "&MKT_CD=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&MBR_NO=" + mktpartcList + "&END_DD=" + $c.stf.getObjectValue(edt_EDate_all) + "&TYPE_CD=3" + "&CHECK_YN=" + scwin.pCheckAll;
        dts_Com_List_2.DataID = encodeURI(url);
        dts_Com_List_2.reset();
        var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=DUE_DIlIGENCE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.select.due.diligene.com.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate_all) + "&{P}param02=" + $c.stf.getObjectValue(edt_EDate_all) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate_all) + "&{P}param04=" + $c.stf.getObjectValue(edt_EDate_all) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate_all) + "&{P}param06=" + $c.stf.getObjectValue(edt_EDate_all) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate_all) + "&{P}param08=" + $c.stf.getObjectValue(edt_EDate_all) + "&{P}param09=" + $c.stf.getObjectValue(edt_SDate_all) + "&{P}param10=" + $c.stf.getObjectValue(edt_EDate_all) + "&{P}param11=" + $c.stf.getObjectValue(edt_SDate_all) + "&{P}param12=" + $c.stf.getObjectValue(edt_EDate_all) + "&{P}param13=" + mktpartcList + "&{P}param14=" + mktpartcList + "&{P}param15=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param16=" + $c.stf.getObjectValue(rdo_MKTCD_all);
        dts_Com_List_3.DataID = encodeURI(url);
        dts_Com_List_3.reset();
        var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=DUE_DIlIGENCE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.select.stock.contrbt.com..condition" + "&{P}param01=" + scwin.periodYYYY + "&{P}param02=" + scwin.periodTmCd + "&{P}param03=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param04=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param05=" + scwin.periodYYYY + "&{P}param06=" + scwin.periodTmCd + "&{P}param07=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param08=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param09=" + scwin.periodYYYY + "&{P}param10=" + scwin.periodTmCd + "&{P}param11=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param12=" + $c.stf.getObjectValue(rdo_MKTCD_all) + "&{P}param13=" + mktpartcList + "&{P}param14=" + mktpartcList;
        dts_Com_List_4.DataID = encodeURI(url);
        dts_Com_List_4.reset();
        txb_title.setValue("< " + cmd_mktpartcList.getText() + " 평가결과> ");
    }
};





// 대표주관사 평가하여 저장한다.( 계산)
scwin.fn_calcul = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=PERIOD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.select.period.calc.condition";
    dts_Period_Check.DataID = encodeURI(url);
    dts_Period_Check.reset();
    var check = dts_Period_Check.getCellData(1, "CHECK_YYYY");
    var res;
    if (check == "1") {
        res = window.confirm("[" + dts_Period_Check.getCellData(1, "YYYY_PERIOD") + "]" + " 대표주관회사평가 데이터를 생성하시겠습니까?");
    } else if (check == "2") {
        res = window.confirm("[" + dts_Period_Check.getCellData(1, "YYYY_PERIOD") + "]" + " 대표주관회사평가 데이터가 있습니다. 다시 계산하시겠습니까?");
    } else if (check == "3") {
        $c.win.alert("[" + dts_Period_Check.getCellData(1, "YYYY_PERIOD") + "]" + " 대표주관회사평가 데이터가 확정되어 계산할 수 없습니다.");
    }
    if (check == "1" || check == "2") {
        if (res) {
            scwin.procJob = "대표주관회사 모의 평가";
            trs_Save.Action = $c.lc.fn_encodeNSession("/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=insertRepMajagntValu");
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Period_Check)";
            var periodSDate = "";
            var periodEDate = "";
            if (dts_Period_Check.getCellData(1, "YYYY") >= scwin.basYYYY) {
                periodSDate = dts_Period_Check.getCellData(1, "YYYY");
                periodEDate = dts_Period_Check.getCellData(1, "YYYY");
                trs_Save.Parameters = "TODATE=" + $c.ut.cGetToday("yyyymmddhhmmss") + ",YYYY=" + dts_Period_Check.getCellData(1, "YYYY") + ",VALU_TM_TP_CD=" + dts_Period_Check.getCellData(1, "VALU_TM_TP_CD") + ",STRT_DD=" + (periodSDate - 1) + "0101" + ",END_DD=" + (periodEDate - 1) + "1231";
            } else {
                trs_Save.Parameters = "TODATE=" + $c.ut.cGetToday("yyyymmddhhmmss") + ",YYYY=" + dts_Period_Check.getCellData(1, "YYYY") + ",VALU_TM_TP_CD=" + dts_Period_Check.getCellData(1, "VALU_TM_TP_CD") + ",STRT_DD=" + dts_Period_Check.getCellData(1, "STRT_DD") + ",END_DD=" + dts_Period_Check.getCellData(1, "END_DD");
            }
            trs_Save.Post();
        }
    }
};
