    var xls_path = $c.session.getExcelDownPath() + today + "_대표주관회사평가내역_STF41400.xls";
    $c.data.saveExcel(grd_Mbr_List_1, "공모가격 적정성", false, false, false, xls_path);
    $c.data.downloadGridViewExcel(grd_Mbr_List_12, "이익지표적정성 ", xls_path, "40");
